export function deepClone(obj) {
    var _out = new obj.constructor;

    var getType = function (n) {
        return Object.prototype.toString.call(n).slice(8, -1);
    }

    for (var _key in obj) {
        if (obj.hasOwnProperty(_key)) {
            _out[_key] = getType(obj[_key]) === 'Object' || getType(obj[_key]) === 'Array' ? deepClone(obj[_key]) : obj[_key];
        }
    }
    return _out;
}


export function getOrDeleteData(store,restApi,loader, url){
    let id = JSON.parse(sessionStorage.getItem('currentUser')).loginUserDetails.userId;
    let param ={
        empId : id
    }
    loader.show();
    restApi.getOrDeleteData(url,null,null).subscribe(data=>{
        loader.hide();
          if(data != null && data != undefined){
            store.dataSourceSubject.next(data);
          }
          else{
            store.dataSourceSubject.next(null);
          }
          store.refreshGrid.next();
      },(err)=>{
        loader.hide()
      })
     
}

