export function encryptUsingAES256(text): any {
  var encrypted = CryptoJS.AES.encrypt(text, "H5mFwjFHIQZ3QhVBYPvYbg==MTIzNDK1");
  
  // CryptoJS.AES.encrypt(
  //   CryptoJS.enc.Utf8.parse(text),
  //   key,
  //   {
  //     keySize: 128 / 8,
  //     iv: iv,
  //     mode: CryptoJS.mode.CBC,
  //     padding: CryptoJS.pad.Pkcs7,
  //   }
  // );
  return encrypted.toString();
}
export function decryptUsingAES256(decString) {
  var decrypted = CryptoJS.AES.decrypt(decString, "H5mFwjFHIQZ3QhVBYPvYbg==MTIzNDK1");
  // var decrypted = CryptoJS.AES.decrypt(decString, key, {
  //   keySize: 128 / 8,
  //   iv: iv,
  //   mode: CryptoJS.mode.CBC,
  //   padding: CryptoJS.pad.Pkcs7,
  // });
  return decrypted.toString(CryptoJS.enc.Utf8);
}

 // Same key used in Java

export function decrypt(encryptedText: string): string {
  let secretKey = '1234567890123456';
  const bytes = CryptoJS.AES.decrypt(encryptedText, CryptoJS.enc.Utf8.parse(secretKey), {
    mode: CryptoJS.mode.ECB,
    padding: CryptoJS.pad.Pkcs7
  });
  return bytes.toString(CryptoJS.enc.Utf8);
}



