//get All date range
export function getDatesInRange(startDate, endDate,datePipe) {
  const start = new Date(new Date(startDate));
  const end = new Date(new Date(endDate));

  const date = new Date(start.getTime());

  const dates = [];

  while (date <= end) {
    dates.push(datePipe.transform(new Date(date), keywords.formateDateOnly));
    date.setDate(date.getDate() + 1);
  }
  return dates;
}

export function removeNullUndefinedEmpty(obj) {
 // console.log("Obj",obj)
  for (const key in obj) {
      if (obj[key] === null || obj[key] === undefined || obj[key] === "" || obj[key].length == 0) {
          delete obj[key];
      }
  }
}


  // Delay function using Promise and setTimeout
  export function delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }